  '[{"id":"A","text":"t = ln4 / λ","diagnostic_error":null},{"id":"B","text":"t = ln(1/4) / λ = −ln4/λ","diagnostic_error":"علامة سالبة في البسط رغم أن t زمن موجب"},{"id":"C","text":"t = λ · ln4","diagnostic_error":"لا عزل صحيح (المقام والبسط انقلبا)"},{"id":"D","text":"t = ln(4/1) · λ","diagnostic_error":"خلط بين ln والضرب في λ"}]'::jsonb,
  'A',
