  '[{"id":"A","text":"n ≈ 0.96 mol","diagnostic_error":null},{"id":"B","text":"n ≈ 1.04 × 10⁻² mol","diagnostic_error":"خطأ في العمود (ضرب T في R صحيح لكن مقام خاطئ)"},{"id":"C","text":"n ≈ 960 mol","diagnostic_error":"عدم القسمة على R·T (حساب P·V فقط)"},{"id":"D","text":"n ≈ 1.6 mol","diagnostic_error":"استعمال درجة الحرارة بالسلسيوس دون تحويل"}]'::jsonb,
