insert into public.diagnostic_questions
  (id, test_id, question_type, skill, primary_skill, secondary_skill, sub_skill, difficulty, question_text, options, correct_option, explanation, diagnostic_tags, weight)
values (
  'PHYV2-050',
  'bac-physics-v2',
  'single_choice',
  'rea-modelize',
  'rea-modelize',
  'mat-calc',
  'rea-modelize',
  5,
  'جسم في سقوط حر مع إهمال مقاومة الهواء: الشرط أن التسارع ثابت (a = g). اختر النموذج الرياضي الصحيح لطبيعة الحركة (بدون سرعة ابتدائية).',
  '[{"id":"A","text":"v(t) = g·t و z(t) = (1/2)g·t²","diagnostic_error":null},{"id":"B","text":"v(t) = g·t و z(t) = g·t²","diagnostic_error":"نسيان المعامل 1/2 في التكامل الثاني"},{"id":"C","text":"v(t) = ثابت و z(t) = v·t","diagnostic_error":"نموذج الحركة المنتظمة (خطأ: a=0)"},{"id":"D","text":"v(t) = v₀ + at و z(t) = v₀t + at²","diagnostic_error":"نموذج هجين صحيح جزئياً لكن بلا 1/2 على at² (تسارع ثابت لكن المعامل خاطئ)"}]'::jsonb,
  'A',
  'بتكامل a = g: v = g·t + v₀ (مع v₀ = 0)، ثم بتكامل v: z = (1/2)g·t² + z₀. النموذج الصحيح فيه المعامل 1/2.',
  '["model_free_fall","double_integration"]'::jsonb,
  1
);
